// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts Список счетов (с balance)
	// (GET /api/accounts)
	ListAccounts(c *gin.Context)
	// CreateAccount Создать счёт
	// (POST /api/accounts)
	CreateAccount(c *gin.Context)
	// GetAccountBalances Сводка балансов + netWorth
	// (GET /api/accounts/balances)
	GetAccountBalances(c *gin.Context)
	// DeleteAccount Удалить счёт
	// (DELETE /api/accounts/{id})
	DeleteAccount(c *gin.Context, id AccountId)
	// GetAccount Получить счёт по ID
	// (GET /api/accounts/{id})
	GetAccount(c *gin.Context, id AccountId)
	// UpdateAccount Обновить счёт (name, manualAdjustment)
	// (PATCH /api/accounts/{id})
	UpdateAccount(c *gin.Context, id AccountId)
	// LoginUser Вход
	// (POST /api/auth/login)
	LoginUser(c *gin.Context)
	// LogoutUser Выход
	// (POST /api/auth/logout)
	LogoutUser(c *gin.Context)
	// GetCurrentUser Текущий пользователь
	// (GET /api/auth/me)
	GetCurrentUser(c *gin.Context)
	// ConfirmPasswordReset Подтвердить сброс и задать новый пароль
	// (POST /api/auth/password-reset/confirm)
	ConfirmPasswordReset(c *gin.Context)
	// RequestPasswordReset Запросить сброс пароля
	// (POST /api/auth/password-reset/request)
	RequestPasswordReset(c *gin.Context)
	// RegisterUser Регистрация пользователя
	// (POST /api/auth/register)
	RegisterUser(c *gin.Context)
	// DeleteAllSessions Завершить все сессии, кроме текущей
	// (DELETE /api/auth/sessions)
	DeleteAllSessions(c *gin.Context)
	// ListSessions Список активных сессий
	// (GET /api/auth/sessions)
	ListSessions(c *gin.Context)
	// VerifyEmail Подтвердить email одноразовым кодом
	// (POST /api/auth/verify-email)
	VerifyEmail(c *gin.Context)
	// ResendVerification Запросить новый verification code
	// (POST /api/auth/verify-email/resend)
	ResendVerification(c *gin.Context)
	// ListCategories Список категорий
	// (GET /api/categories)
	ListCategories(c *gin.Context, params ListCategoriesParams)
	// CreateCategory Создать категорию
	// (POST /api/categories)
	CreateCategory(c *gin.Context)
	// DeleteCategory Удалить категорию
	// (DELETE /api/categories/{id})
	DeleteCategory(c *gin.Context, id CategoryId)
	// GetCategory Получить категорию по ID
	// (GET /api/categories/{id})
	GetCategory(c *gin.Context, id CategoryId)
	// UpdateCategory Обновить категорию
	// (PATCH /api/categories/{id})
	UpdateCategory(c *gin.Context, id CategoryId)
	// SyncPull Инкрементальный pull изменений по курсору
	// (GET /api/sync/pull)
	SyncPull(c *gin.Context, params SyncPullParams)
	// SyncPush Push пакета клиентских операций
	// (POST /api/sync/push)
	SyncPush(c *gin.Context)
	// ListTransactions Список транзакций (cursor pagination)
	// (GET /api/transactions)
	ListTransactions(c *gin.Context, params ListTransactionsParams)
	// CreateTransaction Создать транзакцию
	// (POST /api/transactions)
	CreateTransaction(c *gin.Context, params CreateTransactionParams)
	// DeleteTransaction Удалить транзакцию
	// (DELETE /api/transactions/{id})
	DeleteTransaction(c *gin.Context, id TransactionId)
	// GetTransaction Получить транзакцию по ID
	// (GET /api/transactions/{id})
	GetTransaction(c *gin.Context, id TransactionId)
	// UpdateTransaction Частично обновить транзакцию
	// (PATCH /api/transactions/{id})
	UpdateTransaction(c *gin.Context, id TransactionId)
}

