// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/api/auth/register", wrapper.RegisterUser)
	router.POST(options.BaseURL+"/api/auth/login", wrapper.LoginUser)
	router.POST(options.BaseURL+"/api/auth/logout", wrapper.LogoutUser)
	router.GET(options.BaseURL+"/api/auth/me", wrapper.GetCurrentUser)
	router.DELETE(options.BaseURL+"/api/auth/sessions", wrapper.DeleteAllSessions)
	router.GET(options.BaseURL+"/api/auth/sessions", wrapper.ListSessions)
	router.POST(options.BaseURL+"/api/auth/verify-email", wrapper.VerifyEmail)
	router.POST(options.BaseURL+"/api/auth/verify-email/resend", wrapper.ResendVerification)
	router.POST(options.BaseURL+"/api/auth/password-reset/request", wrapper.RequestPasswordReset)
	router.POST(options.BaseURL+"/api/auth/password-reset/confirm", wrapper.ConfirmPasswordReset)
	router.GET(options.BaseURL+"/api/transactions", wrapper.ListTransactions)
	router.POST(options.BaseURL+"/api/transactions", wrapper.CreateTransaction)
	router.DELETE(options.BaseURL+"/api/transactions/:id", wrapper.DeleteTransaction)
	router.GET(options.BaseURL+"/api/transactions/:id", wrapper.GetTransaction)
	router.PATCH(options.BaseURL+"/api/transactions/:id", wrapper.UpdateTransaction)
	router.GET(options.BaseURL+"/api/accounts", wrapper.ListAccounts)
	router.POST(options.BaseURL+"/api/accounts", wrapper.CreateAccount)
	router.GET(options.BaseURL+"/api/accounts/balances", wrapper.GetAccountBalances)
	router.DELETE(options.BaseURL+"/api/accounts/:id", wrapper.DeleteAccount)
	router.GET(options.BaseURL+"/api/accounts/:id", wrapper.GetAccount)
	router.PATCH(options.BaseURL+"/api/accounts/:id", wrapper.UpdateAccount)
	router.GET(options.BaseURL+"/api/categories", wrapper.ListCategories)
	router.POST(options.BaseURL+"/api/categories", wrapper.CreateCategory)
	router.DELETE(options.BaseURL+"/api/categories/:id", wrapper.DeleteCategory)
	router.GET(options.BaseURL+"/api/categories/:id", wrapper.GetCategory)
	router.PATCH(options.BaseURL+"/api/categories/:id", wrapper.UpdateCategory)
	router.POST(options.BaseURL+"/api/sync/push", wrapper.SyncPush)
	router.GET(options.BaseURL+"/api/sync/pull", wrapper.SyncPull)
}

